    n = len(s)
    lps = [0] * n
    j = 0
    for i in range(1, n):
        while (j > 0 and s[i] != s[j]):
            j = lps[j - 1]
        if s[i] == s[j]:
            j += 1
            lps[i] = j
    return lps

def kmp_search(pattern, text):
    m = len(pattern)
    n = len(text)
    lps = preprocess(pattern + "#" + text)
    count = 0
    for i in range(m + 1, m + n + 1):
        if lps[i] == m:
            count += 1
    return count

def is_cyclic_isomorphic(s1, s2):
    if len(s1) != len(s2):
        return False
    return s2 in (s1 + s1)

